// Explicit live browser check for a candidate generated by the HTTP acceptance tool.
import fs from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {chromium} from '../web/node_modules/playwright/index.mjs';
const [resultPath, outputPath] = process.argv.slice(2);
if (!resultPath || !outputPath) throw new Error('Usage: node scripts/verify_gif_acquisition_browser.mjs RESULT_JSON NEW_OUTPUT_DIR');
const record = JSON.parse(await fs.readFile(resultPath, 'utf8'));
if (!record.passed || !record.files.length) throw new Error('A real passed API result is required');
await fs.mkdir(outputPath, {recursive:false});
const item = record.files[0];
const api = process.env.API_URL || 'http://127.0.0.1:8000';
const token = process.env.DEVICE_TOKEN;
const browser = await chromium.launch({headless:true,channel:process.env.PLAYWRIGHT_CHANNEL||'chrome',args:['--disable-gpu']});
try {
 const context = await browser.newContext({viewport:{width:640,height:480},
  extraHTTPHeaders:token?{Authorization:`Bearer ${token}`}:{}});
 const page = await context.newPage();
 const url = new URL(item.media_url,api).href;
 await page.goto(url);
 await page.locator('img').waitFor();
 await page.waitForFunction(()=>document.querySelector('img').complete && document.querySelector('img').naturalWidth>0);
 const image = page.locator('img');
 const hashes = new Set();
 for(let i=0;i<10;i++) {
  const frame = await image.screenshot({animations:'allow'});
  hashes.add(createHash('sha256').update(frame).digest('hex'));
  if(i<2) await fs.writeFile(path.join(outputPath,`frame-${i}.png`),frame);
  await page.waitForTimeout(90);
 }
 const response = await context.request.get(url);
 if(!response.ok()) throw new Error(`HTTP ${response.status()}`);
 const bytes = await response.body();
 const sha = createHash('sha256').update(bytes).digest('hex');
 await fs.writeFile(path.join(outputPath,'browser-downloaded.gif'),bytes);
 const result={candidate_id:item.candidate_id,web_job_id:record.web_job_id,
  image_loaded:true,distinct_rendered_frames:hashes.size,animation_changed:hashes.size>1,
  browser_download_sha256:sha,api_db_sha256:item.sha256,sha_matches:sha===item.sha256,
  passed:hashes.size>1&&sha===item.sha256,
  note:'Real Chromium/media URL, no response interception; not human target confirmation'};
 await fs.writeFile(path.join(outputPath,'result.json'),JSON.stringify(result,null,2));
 console.log(JSON.stringify(result));
 if(!result.passed) process.exitCode=1;
} finally {await browser.close();}
